import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ChoppingAnimationProps = Record<string, any>;

const ChoppingAnimation: React.FC<ChoppingAnimationProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 10,
  positiveBarLabel = "Skill Level",
  negativeBarLabel = "Energy",
  positiveBarColor = "#22c55e",
  negativeBarColor = "#ef4444",
  stickFigureColor = "#f8fafc",
  treeColor = "#10b981",
  sceneScale = 0.9,
  sceneOffsetX = 0,
  sceneOffsetY = 0,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const totalFrames = durationInSeconds * fps;
  const progress = interpolate(frame, [0, totalFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.linear,
  });

  // Chopping Animation Logic
  const chopCycleLength = Math.floor(fps * 1.2); // One chop every 1.2 seconds
  const cycleFrame = frame % chopCycleLength;

  // The stick figure's arm swings back, chops forward, hits the tree, and recovers
  const armRotation = interpolate(
    cycleFrame,
    [0, Math.floor(chopCycleLength * 0.3), Math.floor(chopCycleLength * 0.45), Math.floor(chopCycleLength * 0.55), chopCycleLength],
    [0, -60, 45, 45, 0], // monotonic input range required by rule 2
    { extrapolateRight: "clamp" }
  );

  // Tree shakes precisely when the axe hits (at 45% of the cycle)
  const treeShake = interpolate(
    cycleFrame,
    [0, Math.floor(chopCycleLength * 0.42), Math.floor(chopCycleLength * 0.45), Math.floor(chopCycleLength * 0.55), Math.floor(chopCycleLength * 0.65), chopCycleLength],
    [0, 0, 8, -4, 0, 0], // impact pushes tree right (+ degrees), then bounds back
    { extrapolateRight: "clamp" }
  );

  // Bars calculation
  const MAX_BAR_HEIGHT = 180;
  const posHeight = progress * MAX_BAR_HEIGHT;
  const negHeight = progress * MAX_BAR_HEIGHT; // Negative meaning it goes 'down' from 0, handled in layout visually

  const isVerticalCanvas = width < height;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        alignItems: "center",
        justifyContent: "center",
        transition: "none",
        overflow: "hidden"
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: isVerticalCanvas ? "column" : "row",
          alignItems: "center",
          justifyContent: "center",
          gap: isVerticalCanvas ? "40px" : "120px",
          transform: `translate(${sceneOffsetX}px, ${sceneOffsetY}px) scale(${sceneScale})`,
          transition: "none",
        }}
      >
        {/* ACTION SCENE: Stick figure and Tree */}
        <svg
          width="400"
          height="500"
          viewBox="0 0 400 500"
          style={{ overflow: "visible", transition: "none" }}
        >
          {/* Ground */}
          <line
            x1="20"
            y1="400"
            x2="380"
            y2="400"
            stroke={stickFigureColor}
            strokeWidth="6"
            strokeLinecap="round"
          />

          {/* Tree */}
          <g
            style={{
              transformOrigin: "295px 400px",
              transform: `rotate(${treeShake}deg)`,
              transition: "none",
            }}
          >
            {/* Trunk */}
            <rect x="280" y="200" width="30" height="200" fill="#78350f" rx="4" />
            {/* Leaves */}
            <circle cx="295" cy="180" r="75" fill={treeColor} />
            <circle cx="240" cy="220" r="60" fill={treeColor} />
            <circle cx="350" cy="220" r="60" fill={treeColor} />
          </g>

          {/* Stick Figure */}
          <g stroke={stickFigureColor} strokeWidth="12" strokeLinecap="round" fill="none">
            {/* Head */}
            <circle cx="150" cy="180" r="30" />
            {/* Body */}
            <line x1="150" y1="210" x2="150" y2="300" />
            {/* Legs */}
            <line x1="150" y1="300" x2="110" y2="400" />
            <line x1="150" y1="300" x2="190" y2="400" />
            {/* Static Left Arm */}
            <line x1="150" y1="230" x2="120" y2="290" />
          </g>

          {/* Swinging Right Arm & Axe */}
          <g
            style={{
              transformOrigin: "150px 230px",
              transform: `rotate(${armRotation}deg)`,
              transition: "none",
            }}
          >
            {/* Arm */}
            <line
              x1="150"
              y1="230"
              x2="220"
              y2="230"
              stroke={stickFigureColor}
              strokeWidth="12"
              strokeLinecap="round"
            />
            {/* Axe Handle */}
            <line
              x1="200"
              y1="100"
              x2="200"
              y2="280"
              stroke="#78350f"
              strokeWidth="10"
              strokeLinecap="round"
            />
            {/* Axe Head */}
            <polygon
              points="200,100 250,90 260,140 200,130"
              fill="#cbd5e1"
              stroke="none"
            />
          </g>
        </svg>

        {/* BARS DASHBOARD */}
        <div
          style={{
            width: "300px",
            height: "400px",
            position: "relative",
            transition: "none",
          }}
        >
          {/* Zero Line */}
          <div
            style={{
              position: "absolute",
              top: "200px",
              width: "100%",
              height: "4px",
              backgroundColor: stickFigureColor,
              opacity: 0.3,
              borderRadius: "2px",
            }}
          />

          {/* Positive Bar (Grows Up) */}
          <div
            style={{
              position: "absolute",
              bottom: "200px",
              left: "40px",
              width: "80px",
              height: `${posHeight}px`,
              backgroundColor: positiveBarColor,
              borderTopLeftRadius: "12px",
              borderTopRightRadius: "12px",
              transition: "none",
            }}
          />
          {/* Positive Label */}
          <div
            style={{
              position: "absolute",
              bottom: `${200 + posHeight + 16}px`,
              left: "80px",
              transform: "translateX(-50%)",
              color: positiveBarColor,
              fontSize: "26px",
              fontWeight: 800,
              whiteSpace: "nowrap",
              transition: "none",
            }}
          >
            {positiveBarLabel}
          </div>

          {/* Negative Bar (Grows Down) */}
          <div
            style={{
              position: "absolute",
              top: "200px",
              left: "180px",
              width: "80px",
              height: `${negHeight}px`,
              backgroundColor: negativeBarColor,
              borderBottomLeftRadius: "12px",
              borderBottomRightRadius: "12px",
              transition: "none",
            }}
          />
          {/* Negative Label */}
          <div
            style={{
              position: "absolute",
              top: `${200 + negHeight + 16}px`,
              left: "220px",
              transform: "translateX(-50%)",
              color: negativeBarColor,
              fontSize: "26px",
              fontWeight: 800,
              whiteSpace: "nowrap",
              transition: "none",
            }}
          >
            {negativeBarLabel}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChoppingAnimation;